<template>
 <section class="training-raid" data-training-raid>
  <div class="training-config"><div class="training-boss"><img :src="$pokemonSprite(bossId)" alt=""><div><small>BOSS D’ENTRAÎNEMENT</small><h4>{{ chosen?.name || 'Choisis ton boss' }}</h4><p>Quatre Pokémon alliés · 1 à 4 dresseurs</p></div></div>
   <label>Niveau du boss <input v-model.number="level" type="number" min="100" max="1000" step="1" inputmode="numeric" data-training-level></label>
   <div class="training-levels"><button v-for="n in [100,200,300,500,1000]" :key="n" type="button" :aria-pressed="level===n" @click="level=n">{{ n }}</button></div>
   <p class="training-safe">Tes Pokémon, leurs PV, leurs objets et leurs PP d’Aventure restent intacts. Aucune XP, aucune récompense. Après création, invite tes amis et préparez ensemble les quatre emplacements du raid.</p>
  </div>
  <label class="training-search">Trouver un boss<input v-model="search" type="search" placeholder="Nom ou numéro…"></label>
  <p v-if="!bosses.length" role="status">{{ error || 'Chargement des boss…' }} <button v-if="error" @click="$emit('reload')">Réessayer</button></p>
  <div class="training-bosses" aria-label="Boss disponibles"><button v-for="p in filtered" :key="p.id" :aria-pressed="p.id===bossId" @click="bossId=p.id"><img :src="$pokemonSprite(p.id)" alt="" loading="lazy"><b>{{ p.name }}</b><small>#{{ p.id }}</small></button></div>
  <form id="training-raid-form" @submit.prevent="launch"/>
 </section>
</template>
<script>
export default{props:{bosses:{type:Array,default:()=>[]},error:String,busy:Boolean,connected:Boolean},data:()=>({bossId:248,level:100,search:''}),computed:{chosen(){return this.bosses.find(p=>p.id===this.bossId);},valid(){return Number.isInteger(this.level)&&this.level>=100&&this.level<=1000;},filtered(){const q=this.search.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return this.bosses.filter(p=>(p.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()+' '+p.id).includes(q));}},mounted(){this.$emit('reload');},methods:{launch(){if(this.valid&&this.chosen)this.$emit('create',{bossId:this.bossId,level:this.level});}}};
</script>
